Here's an example implementation:

```csharp
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using System.IO;

public class WordMerger
{
    public static void MergeDocuments(string source1Path, string source2Path, string destinationPath)
    {
        // Open the source documents
        using (WordprocessingDocument doc1 = WordprocessingDocument.Open(source1Path, true))
        using (WordprocessingDocument doc2 = WordprocessingDocument.Open(source2Path, true))
        {
            // Get the main document part of the first document
            MainDocumentPart mainDocPart1 = doc1.MainDocumentPart;

            // Get the main document part of the second document
            MainDocumentPart mainDocPart2 = doc2.MainDocumentPart;

            // Create a new document part for the merged document
            MainDocumentPart mergedDocPart = WordprocessingDocument.CreatePart();
            mergedDocPart.FeedData(mainDocPart1.GetStream());
            mergedDocPart.FeedData(mainDocPart2.GetStream());

            // Set the properties of the merged document part
            mergedDocPart.Document = mainDocPart1.Document.Clone() as Body;
            mergedDocPart.Document.Body.AppendChild(new Paragraph(new Run(new Text("Page " + (mainDocPart1.NumberOfSections + 1)))));

            // Add the merged document part to the merged document
            WordprocessingDocument mergedDoc = WordprocessingDocument.Create(destinationPath, WordprocessingDocumentType.Document);
            mergedDoc.AddMainDocumentPart(mergedDocPart);

            // Save the merged document
            mergedDoc.Save();
        }
    }
}
```

This code creates a new merged document by copying the content of both source documents while preserving their headers, footers, and designs. It also includes a placeholder text at the end of the merged document indicating the number of sections.

Please note that this is a basic implementation and may require additional customization based on your specific requirements. For example, you might want to handle image merging separately or apply different styles to each section.

