<?php
/*
Plugin Name: Clear Nginx Cache on Theme/Plugin Changes
Description: Clears the Nginx helper cache when a theme or plugin is added, updated, or changed.
Version: 1.0
Author: Your Name
*/

// Exit if accessed directly
if (!defined('ABSPATH')) {
    exit;
}

/**
 * Function to clear Nginx cache on theme/plugin changes
 */
function clear_nginx_cache_on_changes() {
    // Check if the current action is 'activate' (theme/plugin activation)
    if (in_array($_GET['action'], ['activate', 'update'])) {
        // Get the post ID of the activated/theme/plugin
        $post_id = isset($_GET['post']) ? absint($_GET['post']) : null;

        // If no specific post ID is provided, check for the current theme/plugin
        if (!$post_id) {
            $post_id = get_current_theme_fileslug();
        }

        // Get the post object
        $post = get_post($post_id);

        // Only proceed if the post is a theme or plugin
        if ($post && in_array($post->post_type, ['theme', 'plugin'])) {
            // Clear the Nginx cache
            clear_nginx_helper_cache();
        }
    }
}
add_action('admin_init', 'clear_nginx_cache_on_changes');

/**
 * Function to clear Nginx helper cache
 */
function clear_nginx_helper_cache() {
    // Path to the Nginx configuration file
    $nginx_config_path = WP_CONTENT_DIR . '/nginx.conf';

    // Read the Nginx configuration file
    $nginx_config_content = file_get_contents($nginx_config_path);

    // Remove the line containing the helper cache path
    $nginx_config_content = preg_replace('/helper_cache_path\s*=\s*"[^"]+"/m', '', $nginx_config_content);

    // Write the modified content back to the Nginx configuration file
    file_put_contents($nginx_config_path, $nginx_config_content);
}
