```systemverilog
module testbench;
    reg clk = 0;
    reg [31:0] counter = 0;

    initial begin
        $dumpfile("output.vcd");
        $dumpvars(0, testbench);
        forever #5 clk = ~clk; // Clock period of 5 time units
