Certainly! Below is an example of how you can implement old-school raycasting using GLSL in both the vertex shader and fragment shader.

### Vertex Shader

The vertex shader will generate rays from the camera position and direction, and pass the ray information to the fragment shader.

```glsl
#version 330 core

layout(location = 0) in vec3 aPos;
uniform mat4 model;
uniform mat4 view;
uniform mat4 projection;

out RayData {
    vec3 rayOrigin;
    vec3 rayDirection;
} rayData;

void main() {
    // Calculate the ray origin (camera position)
    vec3 rayOrigin = vec3(view * model * vec4(aPos, 1.0));

    // Calculate the ray direction (from the camera to the object's position)
    vec3 rayDirection = normalize(vec3(view * model * vec4(aPos + vec3(0.0, 0.0, 1.0), 1.0)) - rayOrigin);

    rayData.rayOrigin = rayOrigin;
    rayData.rayDirection = rayDirection;

    gl_Position = projection * view * model * vec4(aPos, 1.0);
}
```

### Fragment Shader

The fragment shader will perform the actual raycasting by checking if the ray intersects with any objects in the scene.

```glsl
#version 330 core

in RayData {
    vec3 rayOrigin;
    vec3 rayDirection;
} rayData;

out vec4 FragColor;

uniform sampler2D textureSampler;
uniform bool useTexture;

const float EPSILON = 0.0001; // Small value to avoid division by zero

vec3 intersectRayWithPlane(vec3 rayOrigin, vec3 rayDirection, vec3 planeNormal, vec3 planePoint) {
    float t = -(dot(planePoint - rayOrigin, planeNormal)) / dot(rayDirection, planeNormal);
    return rayOrigin + rayDirection * t;
}

bool intersectRayWithSphere(vec3 rayOrigin, vec3 rayDirection, vec3 sphereCenter, float sphereRadius) {
    vec3 rayToSphere = sphereCenter - rayOrigin;
    float d = length(rayToSphere) - sphereRadius;
    float e = dot(rayDirection, rayDirection);
    float f = dot(rayToSphere, rayToSphere) - d * d;
    float discriminant = f - e * d * d;

    if (discriminant < 0.0) {
        return false;
    }

    float t = (-f - sqrt(discriminant)) / e;
    return t > 0.0;
}

bool intersectRayWithTriangle(vec3 rayOrigin, vec3 rayDirection, vec3 v0, vec3 v1, vec3 v2) {
    vec3 edge1 = v1 - v0;
    vec3 edge2 = v2 - v0;
    vec3 h = cross(rayDirection, edge2);
    float a = dot(edge1, h);

    if (a > -EPSILON && a < EPSILON) {
        return false;
    }

    float f = 1.0 / a;
