import java.net.Socket

class PacketFilterService(private val context: Context) {

    private val socket = Socket("192.168.1.1", 5000) // Replace with your server IP and port

    fun sendPacket(destinationIp: String, data: ByteArray) {
        try {
            val destAddress = InetAddress.getByName(destinationIp)
            socket.getOutputStream().write(data)
            println("Packet sent to $destinationIp")
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

    fun receivePacket(): ByteArray? {
        var receivedData: ByteArray? = null
        try {
            val buffer = ByteArray(1024)
            val inputStream = socket.getInputStream()
            val bytesRead = inputStream.read(buffer)
            if (bytesRead > 0) {
                receivedData = buffer.copyOfRange(0, bytesRead)
                println("Received packet from ${socket.remoteSocketAddress}")
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
        return receivedData
    }

    fun close() {
        try {
            socket.close()
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }
}

