    'job1',
    'job2',
    'job3',
    'job4',
    'job5'
];

$runningThreads = [];
$maxConcurrency = 5;

foreach ($jobs as $job) {
    while (count($runningThreads) >= $maxConcurrency) {
        sleep(1); // Wait until there's room for another thread
    }

    $runningThreads[] = runCoroutine($job);
