/* Stack Frame Concept Program */
/* This program adds 150 numbers using a stack frame and a subroutine */

/* Define constants and variables */
.equ NUMBERS, 150
.equ STACK_SIZE, 8 * NUMBERS /* Assuming each number takes 4 bytes (32-bit) */
.equ TOTAL_SIZE, STACK_SIZE + 4 /* Total size including return address and arguments */

/* Define data section */
.data
    .align 4
    myArray: .space TOTAL_SIZE
    sumOfarray: .word 0 /* Variable to store the sum */

/* Define text section */
.text
.global main
main:
    /* Initialize the stack pointer */
    stmfd sp!, {lr} /* Save LR register and clear stack frame */

    /* Call the memorygenerate macro to create the array */
    bl memorygenerate

    /* Push the first argument (number of elements) onto the stack */
    push {r0}
    mov r0, #NUMBERS

    /* Push the second argument (address of the array) onto the stack */
    push {r1}
    ldr r1, =myArray

    /* Call the addsubroutine macro to add the last two values on the stack */
    bl addsubroutine

    /* Pop the result back into the stack */
    pop {r0}

    /* Store the sum in the sumOfarray variable */
    str r0, [sumOfarray]

    /* Restore the stack pointer */
    ldmfd sp!, {lr} /* Restore LR register and clear stack frame */

    /* Exit the program */
    bx lr

/* Macro to generate an array of numbers from 1 to 150 */
.macro memorygenerate DESTINATION, SIZE
    mov r0, #1
    ldr r1, =\DESTINATION
loop@:
    str r0, [r1]
    add r1, #4
    add r0, #1
    cmp r0, #\SIZE
    ble loop@
.endm

/* Subroutine to add the last two values on the stack */
.addsubroutine:
    /* Load the second value from the stack */
    ldr r2, [sp], #4

    /* Load the first value from the stack */
    ldr r1, [sp], #4

    /* Add the two values and store the result in the second value */
    add r2, r1, r2

    /* Return from the subroutine */
    bx lr

/* End of program */
```

