Certainly! Below is a simple example of how you might implement a "To-Do List" application using a Python dictionary as a stack (LIFO - Last In, First Out). This will allow you to add tasks and remove them in the order they were added.

```python
class ToDoList:
    def __init__(self):
        self.tasks = []

    def add_task(self, task):
        """Add a new task to the end of the list."""
        self.tasks.append(task)
        print(f"Task '{task}' added.")

    def remove_task(self):
        """Remove and return the last task from the list."""
        if not self.tasks:
            print("No tasks available.")
            return None
        task = self.tasks.pop()
        print(f"Removed task: {task}")
        return task

    def view_tasks(self):
        """View all tasks currently in the list."""
        if not self.tasks:
            print("No tasks available.")
        else:
            print("Tasks:")
            for i, task in enumerate(self.tasks, 1):
                print(f"{i}. {task}")

def main():
    todo_list = ToDoList()

    while True:
        print("\nOptions:")
        print("1. Add Task")
        print("2. Remove Task")
        print("3. View Tasks")
        print("4. Exit")

        choice = input("Enter your choice: ")

        if choice == '1':
            task = input("Enter the task: ")
            todo_list.add_task(task)
        elif choice == '2':
            todo_list.remove_task()
        elif choice == '3':
            todo_list.view_tasks()
        elif choice == '4':
            print("Exiting...")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
```

This script provides a basic command-line interface for managing tasks. Users can choose to add tasks, remove tasks, view their current tasks, or exit the program. The use of a list ensures that tasks are managed in a Last-In-First-Out manner, which is typical for stacks.

