    let currentSpriteIndex = -1;

    function createSprite(name) {
        const spriteDiv = document.createElement('div');
        spriteDiv.className = 'sprite';
        spriteDiv.textContent = name || 'New Sprite';
        spriteDiv.onclick = () => setCurrentSprite(spriteDiv);
        return spriteDiv;
    }

    function setCurrentSprite(sprite) {
        if (currentSpriteIndex !== -1) {
            document.querySelectorAll('.sprite').forEach(s => s.classList.remove('selected'));
        }
        sprite.classList.add('selected');
        currentSpriteIndex = Array.from(editor.children).indexOf(sprite);
    }

    function removeSprite(index) {
        if (index >= 0 && index < editor.children.length) {
            editor.removeChild(editor.children[index]);
            currentSpriteIndex = -1;
        }
    }

    function saveSprite() {
        const name = document.getElementById('spriteName').value.trim();
        if (!name) return;

        if (currentSpriteIndex === -1) {
            // Add new sprite
            editor.appendChild(createSprite(name));
        } else {
            // Edit existing sprite
            editor.children[currentSpriteIndex].textContent = name;
        }

        document.getElementById('spriteName').value = '';
    }

    // Initialize the editor with some default sprites
