   ```

2. **Set up your Pinia store**: Ensure you have a global Pinia store set up. For example, if you're using TypeScript, it might look something like this:
   ```typescript
   import { defineStore } from 'pinia';

   export const useGlobalStore = defineStore('global', {
     state: () => ({
       sessionData: null as any,
     }),
