         }
       },
     },
   });
   ```

3. **Use Vue Query with Pinia Store**: You can integrate Vue Query into your component or setup file to handle the query and update the Pinia store accordingly.

Here's an example of how you could configure Vue Query within your main application file (e.g., `main.ts` or `App.vue`):

```typescript
import { createApp } from 'vue';
import App from './App.vue';
import { createPinia } from 'pinia';
import { createQueryClient } from '@tanstack/vue-query';
import { useGlobalStore } from './stores/global'; // Adjust path as necessary

const app = createApp(App);

// Create Pinia instance
const pinia = createPinia();

// Initialize query client
const queryClient = createQueryClient({
  defaultOptions: {
    queries: {
      retry: false, // Disable automatic retries
    },
  },
});

// Add query client to Pinia
pinia.use((store) => {
  store.queryClient = queryClient;
});

// Use Pinia store
app.use(pinia);

// Define query for /get_session
queryClient.prefetchQuery(['session'], () => fetch('/get_session').then(res => res.json()));

// Watch for changes in the query result and update the store
useGlobalStore().$subscribe((mutation, previousValue, currentValue) => {
  if (mutation.type === 'REFETCH' || mutation.type === 'UPDATE') {
    useGlobalStore().sessionData = currentValue;
  }
});

app.mount('#app');
```

In this setup:
- We initialize both Pinia and Vue Query.
- We prefetch the `/get_session` endpoint when the application starts.
- We subscribe to updates from the query results and update our global store whenever there is a change.

