To create a simple Connect-4 game in Python, we can use the `pygame` library for graphics and user input handling. Below is an example of how you might implement this:

```python
import pygame
import sys

# Initialize Pygame
pygame.init()

# Screen dimensions
WIDTH, HEIGHT = 700, 500
CELL_SIZE = 100
ROWS, COLS = 6, 7

# Colors
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)
RED = (255, 0, 0)
GREEN = (0, 255, 0)

# Create the screen
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("Connect Four")

# Fonts
font = pygame.font.Font(None, 36)

def draw_board(board):
    for row in range(ROWS):
        for col in range(COLS):
            color = WHITE if board[row][col] == 0 else BLACK if board[row][col] % 2 == 0 else RED
            rect = pygame.Rect(col * CELL_SIZE, row * CELL_SIZE, CELL_SIZE, CELL_SIZE)
            pygame.draw.rect(screen, color, rect)
            text_surface = font.render(str(board[row][col]), True, BLACK)
            text_rect = text_surface.get_rect(center=rect.center)
            screen.blit(text_surface, text_rect)

def drop_piece(board, row, col, piece):
    board[row][col] += piece

def check_win(board, piece):
    # Check horizontal
    for c in range(COLS - 3):
        for r in range(ROWS):
            if all(board[r][c + i] == piece for i in range(4)):
                return True

    # Check vertical
    for c in range(COLS):
        for r in range(ROWS - 3):
            if all(board[r + i][c] == piece for i in range(4)):
                return True

    # Check diagonal (top-left to bottom-right)
    for c in range(COLS - 3):
        for r in range(ROWS - 3):
            if all(board[r + i][c + i] == piece for i in range(4)):
                return True

    # Check diagonal (bottom-left to top-right)
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if all(board[r - i][c + i] == piece for i in range(4)):
                return True

    return False

def main():
    board = [[0 for _ in range(COLS)] for _ in range(ROWS)]
    current_player = 1

    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()

            if event.type == pygame.MOUSEBUTTONDOWN:
                clicked_row = int(event.pos[1] // CELL_SIZE)
                clicked_col = int(event.pos[0] // CELL_SIZE)

                if board[clicked_row][clicked_col] == 0:
                    drop_piece(board, clicked_row, clicked_col, current_player)
                    if check_win(board, current_player):
                        print(f"Player {current_player} wins!")
                        break
                    current_player *= -1

        screen.fill(WHITE)
        draw_board(board)
        pygame.display.flip()

if __name__ == "__main__":
    main()
```

This code sets up a basic Connect-4 game using Pygame. It includes functions for drawing the board, dropping pieces, checking for wins, and running the main game loop. You'll need to install Pygame (`pip install pygame`) before running the script.

